/**
 * Previews the icon files as they were written to disk.
 *
 * Everything else renders `markSvg` live, which proves the code is right but not that the
 * files are: the PNGs are generated by tools/make-icons.mjs and are what a home screen,
 * a browser tab and an app store actually load. A stale or mis-sized file would pass
 * every other check here and still be what ships.
 *
 * Each is shown at its real pixel size and again enlarged, on both grounds, with the
 * maskable pair circle-cropped the way an Android launcher crops them.
 */

import { chromium } from 'playwright';
import { readFile } from 'node:fs/promises';

const ICONS = [
  { file: 'icon-192.png', label: 'icon-192', shown: 96 },
  { file: 'icon-512.png', label: 'icon-512', shown: 96 },
  { file: 'apple-touch-icon.png', label: 'apple-touch (180)', shown: 96 },
  { file: 'icon-maskable-192.png', label: 'maskable-192', shown: 96, mask: true },
  { file: 'icon-maskable-512.png', label: 'maskable-512', shown: 96, mask: true },
];

const SVGS = [
  { file: 'mark.svg', label: 'mark.svg' },
  { file: 'mark-plain.svg', label: 'mark-plain.svg' },
  { file: 'wordmark.svg', label: 'wordmark.svg' },
];

async function dataUrl(name, type) {
  const bytes = await readFile(new URL(`../icons/${name}`, import.meta.url));
  return `data:${type};base64,${bytes.toString('base64')}`;
}

const pngs = await Promise.all(ICONS.map(async (icon) => ({
  ...icon,
  url: await dataUrl(icon.file, 'image/png'),
})));

const svgs = await Promise.all(SVGS.map(async (svg) => ({
  ...svg,
  url: await dataUrl(svg.file, 'image/svg+xml'),
})));

/** The sizes a mark is actually seen at in chrome, where it either reads or does not. */
const SMALL = [16, 20, 24, 32];

function panel(bg, ink, label, { onDark = false } = {}) {
  /*
   * The shadow belongs to this preview, not to the icon files.
   *
   * A dark drop shadow reads against a light ground and disappears against a dark one,
   * which made the dark panel look as though the icons had lost their depth. They had
   * not — the two panels were simply not showing the same thing. On a dark ground the
   * shadow is replaced by the ambient lift a real launcher gives an icon: a faint pale
   * halo rather than a dark shadow.
   *
   * Icon files deliberately contain no shadow. Every platform composites its own, and a
   * baked-in one is clipped by the maskable safe zone and doubles up under the system's.
   */
  const lift = onDark
    ? '0 10px 26px rgba(0,0,0,.55), 0 0 0 1px rgba(255,255,255,.08), 0 6px 30px rgba(190,180,255,.10)'
    : '0 8px 22px rgba(10,8,30,.3)';

  const files = pngs.map((icon) => `
    <td style="text-align:center">
      <div style="display:inline-block;border-radius:${(icon.shown * 0.225).toFixed(0)}px;
        ${icon.mask ? 'border-radius:50%;' : ''}overflow:hidden;box-shadow:${lift}">
        <img src="${icon.url}" width="${icon.shown}" height="${icon.shown}" style="display:block">
      </div>
      <div style="font:500 10px system-ui;opacity:.55;margin-top:7px">${icon.label}</div>
    </td>`).join('');

  // The favicon case: the real file scaled down by the browser, which is how a tab shows
  // it. Rendering the SVG instead would flatter it.
  const tiny = SMALL.map((size) => `
    <td style="text-align:center">
      <img src="${pngs[0].url}" width="${size}" height="${size}" style="display:block;border-radius:${(size * 0.225).toFixed(1)}px">
      <div style="font:500 9px system-ui;opacity:.5;margin-top:6px">${size}</div>
    </td>`).join('');

  const vectors = svgs.map((svg) => `
    <td style="text-align:center;vertical-align:middle">
      <img src="${svg.url}" style="display:block;height:${svg.file === 'wordmark.svg' ? 34 : 60}px">
      <div style="font:500 10px system-ui;opacity:.55;margin-top:7px">${svg.label}</div>
    </td>`).join('');

  return `
  <div style="background:${bg};color:${ink};padding:22px 26px;border-radius:18px">
    <div style="font:600 11px system-ui;opacity:.5;margin-bottom:14px">${label}</div>
    <table style="border-spacing:18px 10px"><tr>${files}</tr></table>
    <div style="font:600 10px system-ui;opacity:.45;margin:16px 0 2px">icon-192.png scaled down, as a tab shows it</div>
    <table style="border-spacing:16px 8px"><tr>${tiny}</tr></table>
    <div style="font:600 10px system-ui;opacity:.45;margin:16px 0 2px">vector files</div>
    <table style="border-spacing:20px 8px"><tr>${vectors}</tr></table>
  </div>`;
}

const html = `<body style="background:#8a8a8e;margin:0;padding:24px;font-family:system-ui;
  display:flex;flex-direction:column;gap:22px;align-items:flex-start;width:max-content">
  ${panel('#141422', '#ffffff', 'on a dark ground', { onDark: true })}
  ${panel('#f4f4f8', '#1c1c1e', 'on a light ground')}
</body>`;

const browser = await chromium.launch();
const page = await browser.newPage({ deviceScaleFactor: 2 });
await page.setContent(html);
await page.locator('body').screenshot({ path: 'tools/_icon-files.png' });
await browser.close();
console.log('wrote tools/_icon-files.png');
